// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        try c.sudicideAnyone() {
            // after a successful selfdestruct, the contract code is destroyed
            uint256 codeSize;
            assembly { codeSize := extcodesize(address(c)) }
            assertTrue(codeSize == 0);
        } catch {
            // if the call reverted (e.g. not owner), the contract should still exist
            uint256 codeSize;
            assembly { codeSize := extcodesize(address(c)) }
            assertTrue(codeSize > 0);
        }
    }
}

