import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(actor != address(c));
        vm.deal(address(c), amount);
        vm.prank(actor);
        bool ok = true;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(address(c).balance, 0);
        } else {
            assertTrue(true);
        }
    }
}

